MapData::MapData() 
{
	//初期化
	_no = 0;
	InitMap(_no);
	for (int y = 0; y < MAPSIZE_H; y++)
	{
		for (int x = 0; x < MAPSIZE_W1; x++)
		{
			_gMapData[y * MAPSIZE_W + x] = 0;
		}
	}

	// マップチップの読み込み
	LoadDivGraph("res/bg/platformer_simpleA_sheet.png", 30, 8, 4, CHIPSIZE_W, CHIPSIZE_H, _cgChip);
}

MapData::~MapData() 
{
	for(int i = 0; i < 30; i++) {
		DeleteGraph(_cgChip[i]);
	}
}

